import java.util.*;

class Plain {
    final String name;
    Plain(String name) { this.name = name; }
}

class User {
    private final String name;
    private final int age;

    User(String name, int age) { this.name = name; this.age = age; }

    @Override public String toString() { return "User{" + name + ", " + age + "}"; }

    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof User)) return false;
        User other = (User) o;
        return age == other.age && Objects.equals(name, other.name);
    }

    @Override public int hashCode() { return Objects.hash(name, age); }
}

public class Main {
    public static void main(String[] args) {
        Plain a = new Plain("aziz");
        Plain b = new Plain("aziz");
        System.out.println("без equals: " + a.equals(b));

        User u1 = new User("aziz", 20);
        User u2 = new User("aziz", 20);
        System.out.println("с equals: " + u1.equals(u2));
        System.out.println("печать: " + u1);

        // именно поэтому нужен hashCode: множество считает их одним объектом
        Set<User> set = new HashSet<>();
        set.add(u1);
        set.add(u2);
        System.out.println("в множестве: " + set.size());

        Set<Plain> plainSet = new HashSet<>();
        plainSet.add(a);
        plainSet.add(b);
        System.out.println("без equals в множестве: " + plainSet.size());
    }
}

