import java.util.*;

class Box<T> {
    private final List<T> items = new ArrayList<>();

    void add(T item) { items.add(item); }
    T last() { return items.get(items.size() - 1); }
    int size() { return items.size(); }
}

class Util {
    // обобщённый метод с ограничением: T обязан уметь сравниваться
    static <T extends Comparable<T>> T max(List<T> list) {
        T best = list.get(0);
        for (T item : list)
            if (item.compareTo(best) > 0) best = item;
        return best;
    }
}

public class Main {
    public static void main(String[] args) {
        Box<String> words = new Box<>();
        words.add("один");
        words.add("два");
        System.out.println(words.size() + " " + words.last());

        Box<Integer> nums = new Box<>();      // тот же класс, другой тип
        nums.add(10);
        nums.add(42);
        System.out.println(nums.size() + " " + nums.last());

        System.out.println(Util.max(Arrays.asList(3, 9, 5)));
        System.out.println(Util.max(Arrays.asList("груша", "яблоко", "банан")));

        // words.add(42);  // не скомпилируется: Box<String> хранит только строки
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<String> names = Arrays.asList("aziz", "bek", "dilnoza", "umid", "aziz");

        String longUpper = names.stream()
                .filter(n -> n.length() > 3)
                .distinct()
                .map(String::toUpperCase)
                .sorted()
                .collect(Collectors.joining(", "));
        System.out.println(longUpper);

        List<Integer> nums = Arrays.asList(4, 7, 2, 9, 12, 5);
        int sumEven = nums.stream().filter(n -> n % 2 == 0).mapToInt(Integer::intValue).sum();
        System.out.println("сумма чётных: " + sumEven);
        System.out.println("есть больше 10? " + nums.stream().anyMatch(n -> n > 10));
        System.out.println("все положительные? " + nums.stream().allMatch(n -> n > 0));
        System.out.println("сколько больше 4: " + nums.stream().filter(n -> n > 4).count());

        List<Integer> squares = nums.stream().map(n -> n * n).collect(Collectors.toList());
        System.out.println("квадраты: " + squares);

        // группировка — прямой аналог GROUP BY
        Map<Integer, List<String>> byLength = names.stream()
                .distinct()
                .collect(Collectors.groupingBy(String::length));
        System.out.println("по длине: " + byLength);

        // ленивость: без терминальной операции не выполнится ничего
        names.stream().map(n -> { System.out.println("это не напечатается"); return n; });
        System.out.println("конец");
    }
}

