class Pair<T> {
    private final T a;
    private final T b;

    Pair(T a, T b) { this.a = a; this.b = b; }

    T first() { return a; }
    T second() { return b; }

    // новая пара: исходная остаётся нетронутой
    Pair<T> swapped() { return new Pair<>(b, a); }
}

public class Main {
    public static void main(String[] args) {
        Pair<Integer> nums = new Pair<>(1, 2);
        System.out.println(nums.first());
        System.out.println(nums.swapped().first());
        System.out.println(nums.first());

        Pair<String> words = new Pair<>("да", "нет");
        System.out.println(words.swapped().first());
    }
}

