public class Main {
    public static void main(String[] args) {
        List<String> names = Arrays.asList("aziz", "bek", "dilnoza", "umid");
        List<Integer> nums = Arrays.asList(4, 7, 2, 9, 12, 5);

        String result = names.stream()
                .filter(n -> n.length() > 3)
                .map(String::toUpperCase)
                .sorted()
                .collect(Collectors.joining(", "));
        System.out.println(result);

        int sum = nums.stream()
                .filter(n -> n % 2 == 0)
                .mapToInt(n -> n * n)
