import java.util.*;
import java.util.stream.*;

public class Main {
    static Optional<String> findByPrefix(List<String> names, String prefix) {
        return names.stream()
                .filter(n -> n.startsWith(prefix))
                .findFirst();      // findFirst сам возвращает Optional
    }

    public static void main(String[] args) {
        List<String> names = Arrays.asList("aziz", "bek", "dilnoza");
        System.out.println(findByPrefix(names, "d").orElse("нет"));
        System.out.println(findByPrefix(names, "z").orElse("нет"));
        System.out.println(findByPrefix(names, "a").isPresent());
        System.out.println(findByPrefix(names, "b").map(String::toUpperCase).orElse("—"));
    }
}

