import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<String> rows = Arrays.asList(
            "Ташкент:250", "Бухара:100", "Ташкент:400", "Самарканд:180"
        );

        // TreeMap, потому что нужен алфавитный порядок
        Map<String, Integer> totals = rows.stream()
                .map(r -> r.split(":"))
                .collect(Collectors.groupingBy(
                        p -> p[0],
                        TreeMap::new,
                        Collectors.summingInt(p -> Integer.parseInt(p[1]))
                ));

        for (Map.Entry<String, Integer> e : totals.entrySet())
            System.out.println(e.getKey() + " = " + e.getValue());

        Optional<String> leader = totals.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey);
        System.out.println("лидер: " + leader.orElse("нет"));
    }
}
